svg.script:
const SOURCE_URL = "https://lwklearning.github.io/";
const CANDIDATES = [
  "https://cdn.jsdelivr.net/gh/lwklearning/lwklearning.github.io@main/index.html",
  "https://cdn.jsdelivr.net/gh/lwklearning/lwklearning.github.io@master/index.html"
];
const XHTML = "http://www.w3.org/1999/xhtml";
const $ = (id) => document.getElementById(id);
const log = $("log"), frame = $("frame"), status = $("status");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const div = (cls) => { const d = document.createElementNS(XHTML, "div"); if (cls) d.setAttribute("class", cls); log.appendChild(d); return d; };

async function type(text, cls = "", speed = 12) {
  const line = div(cls);
  for (const ch of text) { line.textContent += ch; await sleep(speed); }
  log.scrollTop = log.scrollHeight;
}
function printLine(text, cls = "") { div(cls).textContent = text; log.scrollTop = log.scrollHeight; }

function withBase(html) {
  const base = `<base href="${SOURCE_URL}">`;
  return /<head[^>]*>/i.test(html) ? html.replace(/<head[^>]*>/i, (m) => m + base) : base + html;
}

async function fetchSite() {
  for (const url of CANDIDATES) {
    try {
      const res = await fetch(url, { cache: "no-store" });
      if (res.ok) return { url, html: await res.text() };
      printLine(`  ${res.status} ${res.statusText} :: ${url}`, "dim");
    } catch (err) { printLine(`  network error :: ${url}`, "dim"); }
  }
  throw new Error("could not fetch site from jsDelivr");
}

async function start() {
  $("gate").classList.add("hidden");
  log.classList.remove("hidden");
  status.textContent = "connecting";
  await type("$ open lwklearning.github.io", "", 25);
  await type("resolving cdn.jsdelivr.net ...", "dim");
  await sleep(250);
  await type("fetching index.html via jsDelivr ...", "dim");
  try {
    const { url, html } = await fetchSite();
    await type(`ok: ${url}`);
    await type(`received ${html.length.toLocaleString()} bytes`, "dim");
    await type("mounting into frame ...", "dim");
    await sleep(200);
    frame.srcdoc = withBase(html);
    frame.classList.remove("hidden");
    log.classList.add("hidden");
    status.textContent = "connected";
  } catch (err) {
    status.textContent = "error";
    printLine("");
    printLine("ERROR: " + err.message, "err");
    printLine("The site may be offline, or the default branch may not be main or master.", "warn");
    const retry = document.createElementNS(XHTML, "button");
    retry.textContent = "retry";
    retry.onclick = () => { log.textContent = ""; start(); };
    log.appendChild(retry);
  }
}
$("startBtn").addEventListener("click", start);
